  '\\nTo use this option, please install the NN add-ons from the Flux Forms plugin\\\'s add-ons page.\\n' => '\\n要使用此选项,请从 Flux Forms 插件的附加组件页面安装 NN 附加组件。\\n',
  '\\nSMS Notifications\\n' => '\\n短信通知\\n',
  '\\nEnter the administrators’ mobile numbers to receive SMS notifications, such as alerts or new messages.\\n' => '\\n输入管理员的手机号码以接收短信通知,例如警报或新消息。\\n',
