  '\\nYour subscription needs renewing before the missing add-ons can be restored.\\n' => '\\n您的订阅需要续订,然后才能恢复丢失的加载项。\\n',
  '\\nThe missing add-on files could not be restored. Check the server connection and file permissions, then try again.\\n' => '\\n无法恢复丢失的附加文件。检查服务器连接和文件权限,然后重试。\\n',
  '\\nYou do not have permission to do this.\\n' => '\\n您没有执行此操作的权限。\\n',
  '\\nAll required add-ons were restored.\\n' => '\\n所有必需的加载项均已恢复。\\n',
  '\\nFinish updating Flux Forms\\n' => '\\n完成更新 Flux Forms\\n',
  '\\nSome add-on files are missing\\n' => '\\n某些附加文件丢失\\n',
  '\\nThe plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.\\n' => '\\n该插件已更新,因此必须重新安装其附加组件才能加载此页面。单击下面的按钮进行安装。\\n',
  '\\nOne or more add-on files are missing. Click the button below to reinstall them.\\n' => '\\n缺少一个或多个附加文件。单击下面的按钮重新安装它们。\\n',
  '\\nAutomatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.\\n' => '\\n已尝试自动恢复但未完成。查看以下原因,必要时修复它,然后重试。\\n',
  '\\nRecover add-ons\\n' => '\\n恢复加载项\\n',
  '\\nInstalling add-ons...\\n' => '\\n正在安装附加组件...\\n',
  '\\nInstallation complete.\\n' => '\\n安装完成。\\n',
  '\\nClick to activate the add-ons.\\n' => '\\n单击以激活附加组件。\\n',
  '[[\'Activate add-ons\\n' => '[[\'激活附加组件\\n',
  '\\nInstallation failed. Please try again.\\n' => '\\n安装失败。请重试。\\n',
  '\\nMissing add-ons:\', \'en\']]' => '\\n缺少附加组件:\', \'en\']]',
  '\\nWhy the recovery failed\\n' => '\\n恢复失败的原因\\n',
  '\\nPreparing your form\\n' => '\\n准备您的表格\\n',
  '\\nAdd-ons restored successfully\\n' => '\\n加载项已成功恢复\\n',
  '\\nThe form is being prepared. This page will reload automatically.\\n' => '\\n表格正在准备中。此页面将自动重新加载。\\n',
  '\\nThe page will reload automatically so the restored add-ons can be activated.\\n' => '\\n页面将自动重新加载,以便可以激活恢复的加载项。\\n',
  '\\nReload now\\n' => '\\n立即重新加载\\n',
  '\\nThis form is temporarily unavailable.\\n' => '\\n此表单暂时不可用。\\n',
  '\\nWe could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.\\n' => '\\n我们无法自动恢复所需的表单组件。请稍后重试;站点管理员可以在 Flux Forms 中查看确切的恢复错误。\\n',
  '\\nThe add-on is already installed.\\n' => '\\n该附加组件已安装。\\n',
  '\\nFile access status not checked yet. Please wait.\\n' => '\\n尚未检查文件访问状态。请稍候。\\n',
  '\\nError: server (%s) responded with an invalid request. responded code:%s\\n' => '\\n错误:服务器 (%s) 响应无效请求。响应代码:%s\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the%sserver\\n' => '\\n无法安装 Flux Forms 的附加组件,因为该插件无法连接到%s服务器\\n',
  '\\nYour Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:\\n' => '\\n您的 Easy Form Builder Pro 订阅已过期,因此无法下载 Pro 附加组件。没有它们,插件仍然可以工作。续订您的订阅以恢复所有 Pro 功能:\\n',
  '\\nThe version of the add-on is not compatible with the version of the Flux Forms plugin.\\n' => '\\nThe version of the add-on is not compatible with the version of the Flux Forms plugin.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to download files\\n' => '\\n无法安装 Flux Forms 的附加组件,因为该插件无法下载文件\\n',
  '\\nCannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.\\n' => '\\n无法安装附加组件,因为该服务器已禁用准备下载所需的 PHP 文件系统功能。请要求您的托管提供商启用 mkdir 和重命名,或配置 WordPress 文件系统。\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file\\n' => '\\n无法安装 Flux Forms 的附加组件,因为该插件无法移动下载的文件\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to unzip files\', \'en\']]' => '\\n无法安装 Flux Forms 的附加组件,因为该插件无法解压缩文件\', \'en\']]',
  '\\nTo fix this, sign in to your%s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.\\n' => '\\n要解决此问题,请登录您的%s,从下载部分下载附加处理程序插件,然后安装并激活它。之后,从附加组件处理程序插件激活您需要的附加组件。\\n',
  '\\nWhiteStudio dashboard\\n' => '\\nWhiteStudio 仪表板\\n',
  '\\nThis bundled add-on is missing from the plugin files.\\n' => '\\n插件文件中缺少此捆绑附加组件。\\n',
  '\\nThe add-on server returned an unexpected response.\\n' => '\\n附加服务器返回意外响应。\\n',
  '\\nThe add-on could not be installed.\\n' => '\\n无法安装该附加组件。\\n',
  '\\nThe add-on server did not provide a download URL.\\n' => '\\n附加服务器未提供下载 URL。\\n',
  '\\nThe add-on download URL is not an approved Flux Forms source.\\n' => '\\n附加组件下载 URL 不是经过批准的 Flux Forms 源。\\n',
  '\\nYour server could not reach%1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at%2$sand download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.\\n' => '\\n您的服务器无法到达%1$s,因此无法下载该附加组件。这几乎总是您主机上的防火墙阻止了传出请求,而不是您的许可证问题。要安装附加组件而不需要任何下载,请登录%2$s并下载 Flux Forms 附加组件处理程序插件,然后像安装任何其他插件一样安装它。它包含您的许可证涵盖的所有附加组件。\\n',
  '\\nIf you would rather fix the connection, ask your hosting provider why outgoing requests from%sare being blocked.\\n' => '\\n如果您想修复连接,请询问您的托管提供商为什么来自%s的传出请求被阻止。\\n',
  '\\nFlux Forms: add-on downloads are being blocked\\n' => '\\nFlux Forms:附加组件下载被阻止\\n',
  '\\nAdd-on affected:%s\\n' => '\\n受影响的附加组件:%s\\n',
  '\\nNo response was recorded for this add-on.\\n' => '\\n没有记录此附加组件的响应。\\n',
  '\\nWritable\\n' => '\\n可写\\n',
  '\\nNot writable — the add-on folder cannot be created or extracted into.\\n' => '\\n不可写 — 无法创建或提取附加文件夹。\\n',
  '\\nBlocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.\\n' => '\\n被 WP_HTTP_BLOCK_EXTERNAL 阻止 — 此站点上禁用传出请求。\\n',
  'Allowed' => '允许',
  '\\nDISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.\\n' => '\\nDISABLE_WP_CRON 已打开 — 仅当服务器 cron 任务调用 wp-cron.php 时才会运行后台重试。\\n',
  'Site' => '网站',
  '\\nPage that needed it\\n' => '\\n需要它的页面\\n',
  '\\nPlugin version\\n' => '\\n插件版本\\n',
  'WordPress' => 'WordPress',
  '\\nAdd-on folder\\n' => '\\n附加文件夹\\n',
  '\\nOutgoing requests\\n' => '\\n传出请求\\n',
  '\\nWP-Cron\\n' => '\\nWP-Cron\\n',
  '\\nAttempts made\\n' => '\\n已尝试\\n',
  '\\nFlux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.\\n' => '\\nFlux Forms 无法自动重新安装其附加文件。依赖这些加载项的表单将向访问者显示临时消息,直到此问题得到解决。\\n',
  '\\nWhat is missing\\n' => '\\n缺少什么\\n',
  '\\nDiagnostics\\n' => '\\n诊断\\n',
  '\\nWhat to do next\\n' => '\\n下一步做什么\\n',
  '\\nOpen Flux Forms in your dashboard and use the Recover add-ons button.\\n' => '\\n在仪表板中打开 Flux Forms 并使用“恢复加载项”按钮。\\n',
  '\\nIf the add-on folder is not writable, ask your host to allow writing to the plugin folder.\\n' => '\\n如果附加文件夹不可写,请请求主机允许写入插件文件夹。\\n',
  '\\nIf outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.\\n' => '\\n如果传出请求被阻止,请请求您的主机允许连接到 Flux Forms 更新服务器。\\n',
  '\\nIf your Pro subscription has expired, renew it to restore the Pro add-ons.\\n' => '\\n如果您的 Pro 订阅已过期,请续订以恢复 Pro 附加组件。\\n',
  '\\nWe have made some updates. Please wait a few minutes before trying again.\\n' => '\\n我们做了一些更新。请等待几分钟,然后重试。\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server\\n' => '\\n无法安装 Flux Forms 的附加组件,因为该插件无法连接到whitestudio.team 服务器\\n',
  '\\nOne of the free features\\n' => '\\n免费功能之一\\n',
  '\\nImportant: Caching Plugin May Affect Flux Forms\\n' => '\\n重要提示:缓存插件可能会影响 Flux 形式\\n',
  '\\nThe following caching plugins are active on your site:\\n' => '\\n以下缓存插件在您的网站上处于活动状态:\\n',
  '\\nPlugin Name\\n' => '\\n插件名称\\n',
  '\\nSlug\\n' => '\\n子弹\\n',
  '\\nPlease note that these plugins may affect the functionality of Flux Forms.\\n' => '\\n请注意,这些插件可能会影响 Flux Forms 的功能。\\n',
  '\\nIf you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.\\n' => '\\n如果您遇到任何问题,请从缓存中排除发布表单的页面或禁用这些插件。有关如何设置此排除的详细指南,请参阅相应缓存插件的文档。\\n',
  '\\nSent by\\n' => '\\n发送者\\n',
  '\\nAction needed: Flux Forms Pro is paused on%s\\n' => '\\n需要采取的措施:Flux Forms Pro 在%s上暂停\\n',
  '\\nFlux Forms could not confirm your Pro licence for%1$sdays in a row, so the Pro features on%2$sare paused for now.\\n' => '\\nFlux Forms 连续%1$s天无法确认您的 Pro 许可证,因此%2$s上的 Pro 功能暂时暂停。\\n',
  '\\nYour forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.\\n' => '\\n您的表单、条目和设置不会受到影响,所有免费功能都将继续运行,并且您的激活码仍然会被存储 — 没有任何内容被删除。\\n',
  '\\nOpen%1$sYT Form → Settings%2$sand press%1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.\\n' => '\\n打开%1$sYT 表单 → 设置%2$s并按%1$s保存%2$s。立即再次检查许可证;如果连接恢复,Pro 将在一分钟内打开。\\n',
  '\\nStill paused? Ask your hosting provider to allow outgoing HTTPS connections to%s— a firewall, proxy or regional block is the usual cause — then repeat step 1.\\n' => '\\n还暂停吗?请您的托管提供商允许到%s的传出 HTTPS 连接(防火墙、代理或区域阻止是常见原因),然后重复步骤 1。\\n',
  '\\nIf your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.\', \'en\']]' => '\\nIf your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.\', \'en\']]',
  'Reason' => '原因',
  '\\nFirst failed check\\n' => '\\n第一次检查失败\\n',
  '\\ngrace period\\n' => '\\n宽限期\\n',
  '%s days' => '%s天',
  '\\nActivation code\\n' => '\\n激活码\\n',
  '\\nError code\\n' => '\\n错误代码\\n',
  '\\nHow to bring Pro back\\n' => '\\n如何恢复 Pro\\n',
  '\\nCheck my licence now\\n' => '\\n立即检查我的许可证\\n',
  '\\nStill stuck? Send the details above to%1$sour support team%2$sand we will take it from there.\\n' => '\\n还是卡住了?将上述详细信息发送给%1$s我们的支持团队%2$s,我们将从那里获取。\\n',
  '\\nThe licence server answered with an error and could not confirm your licence.\\n' => '\\n许可证服务器回答错误,无法确认您的许可证。\\n',
  '\\nYour website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.\\n' => '\\n您的网站无法访问许可证服务器 - 几乎总是托管端的网络、防火墙或 DNS 限制。\\n',
  '\\nThe licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.\\n' => '\\n许可证服务器的答案到达时已损坏,通常是因为安全插件、代理或 CDN 在途中更改了它。\\n',
  '\\nThe licence check could not be completed.\\n' => '\\n无法完成许可证检查。\\n',
  '[[\'Your activation code has expired!\\n' => '[[\'您的激活码已过期!\\n',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue using the%sadd-on and all Pro features, please renew your subscription.\\n' => '\\n您的 Easy Form Builder Pro 订阅已过期。要继续使用%s插件和所有 Pro 功能,请续订您的订阅。\\n',
  '\\nRenew Subscription\\n' => '\\n续订订阅\\n',
  '\\nPro Version Required\\n' => '\\n需要专业版\\n',
  '\\nThe%sadd-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.\\n' => '\\n%s附加组件是 Pro 功能。请升级到 Flux Forms Pro 才能访问此功能。\\n',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running,%1$sRenew your subscription now.%2$s\\n' => '\\n您的 Easy Form Builder Pro 订阅已过期。要继续享受所有 Pro 功能并保持您的表单正常运行,请立即续订%1$s。%2$s\\n',
  '\\nThe payment could not be verified yet.\\n' => '\\n尚无法验证付款。\\n',
  '\\nThis payment provider does not support refunds from the site.\\n' => '\\n该支付提供商不支持从网站退款。\\n',
  'Completed' => '已完成',
  'Active' => '活跃',
  '\\nTrial\\n' => '\\n试用\\n',
  'Pending' => '待定',
  'Processing' => '加工',
  '\\nCanceled\\n' => '\\n已取消\\n',
  '\\nAmount mismatch\\n' => '\\n金额不匹配\\n',
  'Past due' => '逾期',
  '\\nUnpaid\\n' => '\\n未付款\\n',
  '\\nIncomplete\\n' => '\\n不完整\\n',
  '\\nExpired\\n' => '\\n已过期\\n',
  'Refunded' => '已退款',
  'Partly refunded' => '部分退款',
  '\\nSorry, you are not allowed to access this page.\\n' => '\\n抱歉,您无权访问此页面。\\n',
  '\\nPayments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.\\n' => '\\n通过您的表格从每个支付提供商处进行付款。 API 密钥和活动提供商在插件设置页面的“付款”选项卡上设置。\\n',
  'Settings saved.' => '设置已保存。',
  '\\nA Stripe webhook signing secret starts with "whsec_".\\n' => '\\nStripe Webhook 签名密钥以“whsec_”开头。\\n',
  '\\nProviders and webhooks\\n' => '\\n提供程序和 webhook\\n',
  '\\nConfigured\\n' => '\\n已配置\\n',
  '\\nNot configured\', \'en\']]' => '\\n未配置\', \'en\']]',
  '\\nWebhook URL for this provider (if it sends payment notifications):\\n' => '\\n此提供商的 Webhook URL(如果它发送付款通知):\\n',
  '\\nRecent payments\\n' => '\\n最近付款\\n',
  '\\nNo payments yet.\\n' => '\\n尚未付款。\\n',
  '\\nConfirmation code\\n' => '\\n确认码\\n',
  'Provider' => '提供者',
  'Type' => '类型',
  'Amount' => '金额',
  'Status' => '状态',
  '\\nTransaction ID\\n' => '\\n事务 ID\\n',
  '\\nSubscription\\n' => '\\n订阅\\n',
  '[[\'One-time\\n' => '[[\'一次\\n',
  '\\nThe latest%dpayments are shown.\\n' => '\\n显示最新的%d付款。\\n',
  '\\nTest provider (development only)\\n' => '\\n测试提供程序(仅限开发)\\n',
  '[[\'Test outcome\\n' => '[[\'测试结果\\n',
  '\\nApprove every payment\\n' => '\\n批准每笔付款\\n',
  '\\nDecline every payment\\n' => '\\n拒绝每笔付款\\n',
  '\\nNo money is taken. Development only.\\n' => '\\n没有拿钱。仅限开发。\\n',
  '\\nTEST MODE: no card is charged.\\n' => '\\n测试模式:不向卡收费。\\n',
  '\\nTest provider: the payment was declined.\\n' => '\\n测试提供商:付款被拒绝。\\n',
  '[[\'Publishable key\\n' => '[[\'可发布密钥\\n',
  'Secret key' => '秘钥',
  '\\nStripe is not configured on this site. Please contact the site administrator.\\n' => '\\n此站点上未配置 Stripe。请联系站点管理员。\\n',
  '\\nThe payment method of this form is not supported.\\n' => '\\n不支持此表单的付款方式。\\n',
  '\\nThe payment could not be started. Please try again.\\n' => '\\n付款无法开始。请重试。\\n',
