  '\\nReasons\\n' => '\\n原因\\n',
  '\\nSystem readiness\\n' => '\\n系统准备情况\\n',
  '\\nHuman Shield checks these functions before enforcing security rules.\\n' => '\\nHuman Shield 在执行安全规则之前检查这些功能。\\n',
  '\\nPHP requirements are ready.\\n' => '\\nPHP 要求已准备就绪。\\n',
  '\\nSome required PHP functions are unavailable.", \'en\']]' => '\\n一些必需的 PHP 函数不可用。", \'en\']]',
  '\\nREST API:\\n' => '\\nREST API:\\n',
  '\\navailable\\n' => '\\n可用\\n',
  '\\nmissing\\n' => '\\n失踪\\n',
  '\\nTables:\\n' => '\\n表格:\\n',
  '\\nready\\n' => '\\n准备好了\\n',
  '\\nnot ready yet\\n' => '\\n尚未准备好\\n',
  '\\nRecommended only after you verify PHP functions and tables are ready.\\n' => '\\n仅在验证 PHP 函数和表准备就绪后才建议使用。\\n',
  '\\nTrust proxy IP headers\\n' => '\\n信任代理 IP 标头\\n',
  '\\nUse forwarding headers only when the immediate peer matches the trusted proxy list below.\\n' => '\\n仅当直接对等方与下面的可信代理列表匹配时才使用转发标头。\\n',
  '\\nTrusted proxy IPs\\n' => '\\n受信任的代理 IP\\n',
  '\\nOne exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.\\n' => '\\n每行一个精确的 IP 或通配符前缀。仅添加您的负载均衡器/CDN 出口地址;当源可直接到达时,将其保留为空。\\n',
  '\\nStore raw behavior metrics\\n' => '\\n存储原始行为指标\\n',
  '\\nKeep off for privacy unless debugging a rollout.\\n' => '\\n出于隐私考虑,请保持关闭状态,除非调试部署。\\n',
  '\\nLog retention days\\n' => '\\n日志保留天数\\n',
  '\\nHow long events should be retained.\\n' => '\\n事件应保留多长时间。\\n',
  '\\nClient attestation timeout\\n' => '\\n客户端证明超时\\n',
  '\\nMilliseconds before the browser falls back to the normal request.\\n' => '\\n浏览器回退到正常请求之前的毫秒数。\\n',
  '\\nIf a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.\\n' => '\\n如果需要的 PHP 功能被禁用,请在 php.ini disable_functions 中启用它或请求主机允许它。缓存和安全插件不得缓存或重写来自 /wp-json/EmsfbShield/v1/* 的 POST 响应。\\n',
  '\\nSecurity & Spam Protection tabs\\n' => '\\n安全和垃圾邮件防护选项卡\\n',
  '\\nSecurity log export is unavailable because this server has disabled a required PHP function:%s. Ask your hosting provider to enable it.\\n' => '\\n安全日志导出不可用,因为该服务器已禁用所需的 PHP 功能:%s。请您的托管提供商启用它。\\n',
  '\\nSecurity log export is unavailable because this server has disabled required PHP functions:%s. Ask your hosting provider to enable them.\\n' => '\\n安全日志导出不可用,因为该服务器已禁用所需的 PHP 功能:%s。请您的托管提供商启用它们。\\n',
