  '\\nUpload Dataset\\n' => '\\n上传数据集\\n',
  '\\nIn Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.\', \'en\']]' => '\\n在表单生成器中,打开表单设置并启用“自动填充”。选择您的数据集,然后将元素映射到数据集字段作为搜索条件。\', \'en\']]',
  '\\nEnable Auto-Populate\\n' => '\\n启用自动填充\\n',
  '[[\'For each target field, enable "Auto-Populate to automatically populate this field" and select the dataset column to auto-populate.\\n' => '[[\'对于每个目标字段,启用“自动填充以自动填充此字段”并选择要自动填充的数据集列。\\n',
  '\\nMap Fields\\n' => '\\n映射字段\\n',
