  'Display the IP addresses of users in the response box.' => '\\n在响应框中显示用户的 IP 地址。\\n',
  'Persia Payment Add-on' => '\\n波斯支付插件\\n',
  'The Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.' => '\\nFlux Forms 的波斯支付插件使您能够将您的网站与波斯支付连接起来,以处理付款、捐赠和在线订单。\\n',
  'Jalali Date Add-on' => '\\nJalali 日期插件\\n',
  'The Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.' => '\\nJalali 日期插件允许您将 Jalali 日期字段添加到表单中,并创建包含此 Shamsi 日期字段的任何类型的表单。\\n',
  'Hijri Date Add-on' => '\\n回历日期插件\\n',
  'The Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.' => '\\n回历日期插件允许您将回历日期字段添加到表单中并创建包含此字段的任何类型的表单。\\n',
  'SMS service Add-on' => '\\n短信服务插件\\n',
  'The SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.' => '\\nSMS 服务插件使您能够在您或您的客户收到新消息或回复时接收通知 SMS 消息。\\n',
  'Please install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.' => '\\n请安装 Hijri 或 Jalali 日期插件。您不能同时安装这两个附加组件。\\n',
  'Response box' => '\\n响应框\\n',
  'Regions Drop-Down' => '\\n区域下拉列表\\n',
  'You are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.' => '\\n您看到此消息是因为正在安装所需的附加组件。请等待几分钟,然后再次访问此页面。如果超过五分钟但没有任何反应,请联系 Whitestudio.team 的 Flux Forms 支持团队。\\n',
  'The cell phone number is incorrect' => '\\n手机号码不正确\\n',
  'Invalid country code' => '\\n国家/地区代码无效\\n',
  'The cell phone number is too short' => '\\n手机号码太短\\n',
  'The cell phone number is too long' => '\\n手机号码太长\\n',
  'Please select the number of countries to display within an acceptable range.' => '\\n请在可接受的范围内选择要显示的国家/地区数量。\\n',
  'Disabled Field' => '\\n禁用字段\\n',
  'Hidden Field' => '\\n隐藏字段\\n',
  'Select a country to display a list of states/provinces.' => '[[\'选择一个国家/地区以显示州/省列表。\\n',
  'Select a state/province to display a list of cities.' => '\\n选择一个州/省以显示城市列表。\\n',
  'SMS Service Add-on' => '\\n短信服务插件\\n',
  'This field is currently unavailable. Please contact the site administrator.' => '[[“该字段当前不可用。请联系站点管理员。\\n',
  'Would you like to customize the form using the colors of the active template?' => '\\n您想使用活动模板的颜色自定义表单吗?\\n',
  'Flux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.' => '\\nFlux Forms 使用了活动模板的颜色。请为下面的每个选项选择一种颜色,以根据模板的颜色自定义您正在创建的表单。通过为下面的每个选项选择颜色,与该功能关联的所有表单字段的颜色将相应更改。\', \'en\']]',
  'Buttons text colors' => '\\n按钮文本颜色\\n',
  'attached files' => '\\n附加文件\\n',
