  'Show attributes' => '\\n显示属性\\n',
  'Hide attributes' => '\\n隐藏属性\\n',
  'The ID length should be at least 3 characters long.' => '\\nID 长度应至少为 3 个字符。\\n',
  'The ID value must be unique, as it is already being used in this field. Please try a new, unique value.' => '\\nID 值必须是唯一的,因为它已在此字段中使用。请尝试一个新的、唯一的值。\\n',
  'Image picker' => '\\n图像选择器\\n',
