  'The Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.' => '\\n条件逻辑插件可根据特定用户输入或条件规则启用动态和交互式表单。它允许定制高度个性化的表单,以满足用户的独特需求。\\n',
  'The Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.' => '\\n条件逻辑模块加载失败。请刷新页面;如果问题仍然存在,请停用并重新激活条件逻辑加载项。\\n',
