  'Are you sure you want to duplicate the "%s" ?' => '\\n您确定要复制“%s”吗?\\n',
  'We are sorry, the booking time for the %s option has expired. Please choose from the other available options.' => '\\n很抱歉,%s选项的预订时间已过期。请从其他可用选项中进行选择。\\n',
  'We are sorry, the %s option is currently at full capacity. Please choose from the other available options.' => '\\n很抱歉,%s选项当前已满。请从其他可用选项中进行选择。\\n',
  '%s Payment Add-on' => '\\n%s付款插件\\n',
  'The %s add-on for Flux Forms enables you to integrate your WordPress site with %s for payment processing, donations, and online orders.' => '\\nFlux Forms 的%s插件使您能够将 WordPress 网站与%s集成,以进行付款处理、捐赠和在线订单。\\n',
