  'Flux Donate is active but did not take over payments (filter flxb_own_payments is off?). Flux Forms uses its own Stripe settings.' => '[[\'Flux Donate 处于活动状态,但未接管付款(过滤器 flxb_own_ payment 已关闭?)。 Flux Forms 使用自己的 Stripe 设置。\\n',
