  'Not active, but %d active automation creates or sends certificates; it will fail.' . chr(0) . 'Not active, but %d active automations create or send certificates; they will fail.' => '[[\'不活动,但%d活动自动创建或发送证书;他们会失败。\', \'en\']]',
  'Not active. Needed only for certificate automations.' => '\\n未激活。仅证书自动化需要。\\n',
