  'Keys are set; %d form uses reCAPTCHA.' . chr(0) . 'Keys are set; %d forms use reCAPTCHA.' => '\\n按键已设置;%d表单使用 reCAPTCHA。%d表单使用 reCAPTCHA。\\n',
