  'Trust proxy IP headers' => '\\n信任代理 IP 标头\\n',
  'Use forwarding headers only when the immediate peer matches the trusted proxy list below.' => '\\n仅当直接对等方与下面的可信代理列表匹配时才使用转发标头。\\n',
  'Trusted proxy IPs' => '\\n受信任的代理 IP\\n',
  'One exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.' => '\\n每行一个精确的 IP 或通配符前缀。仅添加您的负载均衡器/CDN 出口地址;当源可直接到达时,将其保留为空。\\n',
  'Store raw behavior metrics' => '\\n存储原始行为指标\\n',
