  'If a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.' => '\\n如果需要的 PHP 功能被禁用,请在 php.ini disable_functions 中启用它或请求主机允许它。缓存和安全插件不得缓存或重写来自 /wp-json/EmsfbShield/v1/* 的 POST 响应。\\n',
