  'Some plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.' => '\\n某些插件文件丢失,因此插件停止加载以保持网站运行。请从插件页面重新安装 Flux Forms - 您的表单、消息和设置将保留。\\n',
